// Clasifica un bulto por su peso. Las cuatro ramas se evalúan EN ORDEN: gana la primera cuya condición da true.
function categoria(kg) {
  if (kg <= 5) {
    return "paquete chico";
  } else if (kg <= 20) {
    return "bulto mediano";
  } else if (kg <= 50) {
    return "bulto pesado";
  } else {
    return "carga especial";
  }
}

console.log("0,5 kg ->", categoria(0.5));
console.log("5 kg   ->", categoria(5));
console.log("5,1 kg ->", categoria(5.1));
console.log("35 kg  ->", categoria(35));
console.log("80 kg  ->", categoria(80));

