// Con break, y con dos casos que comparten rama a propósito
function plazo(zona) {
  let dias;
  switch (zona) {
    case "caba":
    case "gba":
      dias = 1;
      break;
    case "interior":
      dias = 4;
      break;
    default:
      dias = null;
  }
  return dias;
}
