// Pirámide: la regla de verdad (despachar) queda enterrada en el tercer nivel
function despachoPiramide(pagado, direccion, stock) {
  if (pagado) {
    if (direccion !== "") {
      if (stock > 0) {
        return "despachar";
      } else {
        return "esperar stock";
      }
    } else {
      return "pedir dirección";
    }
  } else {
    return "esperar pago";
  }
}

// Cláusulas de guarda: cada caso que impide seguir se resuelve arriba y se sale
function despachoGuardas(pagado, direccion, stock) {
  if (!pagado) return "esperar pago";
  if (direccion === "") return "pedir dirección";
  if (stock <= 0) return "esperar stock";
  return "despachar";
}

console.log(despachoPiramide(true, "Av. Rivadavia 100", 3), "|", despachoGuardas(true, "Av. Rivadavia 100", 3));
