// REGLAS INVENTADAS para el ejemplo: pesos de ejemplo, no son tarifas reales de nadie.
function tarifa(zona, kg, urgente) {
  // 1. Validar: sin un peso válido no hay nada que calcular
  if (typeof kg !== "number" || Number.isNaN(kg) || kg <= 0) {
    return "pedido inválido: peso";
  }

  // 2. Precio base según la zona
  let base;
  switch (zona) {
    case "caba":     base = 4000;  break;
    case "gba":      base = 6500;  break;
    case "interior": base = 11000; break;
    default:
      return "zona desconocida";
  }

  // 3. Multiplicador según el peso (primera condición verdadera gana)
  let factor;
  if (kg <= 5) {
    factor = 1;
  } else if (kg <= 20) {
    factor = 1.5;
  } else if (kg <= 50) {
    factor = 2.2;
  } else {
    return "cotización manual (más de 50 kg)";
  }

  // 4. Recargo por urgencia: una elección entre dos valores
  const subtotal = base * factor;
  const total = urgente ? subtotal * 1.25 : subtotal;
  return Math.round(total);
}

